 'Звезда':'Star','звезда':'Star','кристалл':'Crystal','орбита':'Orbit','комета':'Comet','корона':'Crown','орбиты':'Orbits','кристаллы':'Crystals','звёздная пыль':'Stardust','руны':'Runes','полумесяц':'Crescent Moon','кометы':'Comets','лунные камни':'Moonstones','розы':'Roses','созвездия':'Constellations','Звёздный узор':'Star Pattern',
 'classic':'Classic','chrome':'Chrome','holographic':'Holographic','crystal':'Crystal','neon':'Neon','ember':'Ember','ice':'Ice','shadow':'Shadow','royal':'Royal','candy':'Candy',
