 modal.dataset.giftId=String(item.id);
 const art=modal.querySelector('.gift-direct-art');art.innerHTML=typeof window.pulseGiftSvg==='function'?window.pulseGiftSvg(item):giftArtwork(item);
 modal.querySelector('.gift-direct-name').textContent=item.name||'Подарок';
